-- The business that owns a book, and the accounts of that book.
--
-- The identity of a business is generated by the database: it is a counter
-- of the businesses and not the document of a person. The owner is the
-- owner, and it is not the key. A person may own more than one business,
-- and the bakery of tomorrow is a second row of this table with an identity
-- of its own: the key space is the businesses, never the people.
--
-- The rule of the domain is that a person has exactly one personal
-- business, and the table holds the same rule as a defense in depth: the
-- partial unique index refuses a second personal business of the same
-- owner, and it leaves the other kinds free.
--
-- The name of an account is unique inside the business that owns it: the
-- person reads the accounts of their book by name.
--
-- The optional columns are NULL when the value is not set, as in the table
-- of the people. An empty string is a different fact, and the library never
-- writes one.

-- +goose Up
CREATE TABLE businesses (
    id         BIGINT      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    owner_id   BIGINT      NOT NULL REFERENCES users (id),
    kind       TEXT        NOT NULL,
    name       TEXT        NOT NULL,
    currency   TEXT        NOT NULL DEFAULT 'COP',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT businesses_kind_check CHECK (kind IN ('personal', 'business')),
    CONSTRAINT businesses_name_not_empty_check CHECK (name <> ''),
    CONSTRAINT businesses_currency_not_empty_check CHECK (currency <> '')
);

CREATE UNIQUE INDEX businesses_one_personal_per_owner
    ON businesses (owner_id) WHERE kind = 'personal';

CREATE TABLE accounts (
    id           BIGINT      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    business_id  BIGINT      NOT NULL REFERENCES businesses (id),
    kind         TEXT        NOT NULL,
    name         TEXT        NOT NULL,
    counterparty TEXT        NULL,
    due_date     DATE        NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT accounts_kind_check CHECK (kind IN ('asset', 'liability', 'income', 'expense', 'equity')),
    CONSTRAINT accounts_name_not_empty_check CHECK (name <> ''),
    CONSTRAINT accounts_debt_check CHECK (
        kind IN ('liability', 'asset')
        OR (counterparty IS NULL AND due_date IS NULL)
    )
);

CREATE UNIQUE INDEX accounts_name_unique ON accounts (business_id, name);

-- +goose Down
DROP TABLE accounts;
DROP TABLE businesses;
